using System;using System.Collections.Generic;using System.IO;using System.Reflection;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class AudioContactChecks
{
 static readonly BindingFlags Flags=BindingFlags.NonPublic|BindingFlags.Instance;
 static object Call(object o,string name,params object[] a)=>o.GetType().GetMethod(name,Flags).Invoke(o,a);
 static void Need(bool b,string text){if(!b)throw new Exception(text);}
 static List<string> report=new List<string>();static int failures;
 static void Check(string name,Action test){try{EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);test();report.Add("PASS "+name);}catch(Exception e){failures++;report.Add("FAIL "+name+": "+e.GetBaseException().Message);}}
 static PlayerHealth Player(){var p=new GameObject("Player");p.AddComponent<Rigidbody2D>();p.AddComponent<CapsuleCollider2D>();var health=p.AddComponent<PlayerHealth>();Call(health,"Awake");return health;}
 static EnemyHealth Enemy(){var p=new GameObject("Slime");p.layer=10;p.AddComponent<Rigidbody2D>();p.AddComponent<BoxCollider2D>();var health=p.AddComponent<EnemyHealth>();Call(health,"Awake");return health;}
 public static void Run(){
 Check("contact removes 20 HP once across multiple slime colliders",()=>{var p=Player();var c=p.gameObject.AddComponent<PlayerEnemyContact>();Call(c,"Awake");var e=Enemy();Need(c.TryContact(e),"First hit missing");Need(!c.TryContact(e)&&!c.TryContact(Enemy()),"Repeated damage");Need(p.currentHealth==80,"Wrong amount");});
 Check("two-second cooldown works without a SpriteRenderer",()=>{var p=Player();Need(p.TryTakeDamage(20),"First hit");Call(p,"Tick",1.99f);Need(!p.TryTakeDamage(20),"Early second hit");Call(p,"Tick",.02f);Need(p.TryTakeDamage(20)&&p.currentHealth==60,"Cooldown never expired");});
 Check("dash excludes only enemy collision, restores original flags and has exit grace",()=>{var p=Player();var body=p.GetComponent<Collider2D>();body.excludeLayers=1<<12;var c=p.gameObject.AddComponent<PlayerEnemyContact>();Call(c,"Awake");var e=Enemy();e.transform.position=Vector3.right*20;Physics2D.SyncTransforms();c.BeginDash();Need((body.excludeLayers.value&(1<<10))!=0,"No phasing");Need((body.excludeLayers.value&((1<<8)|(1<<9)))==0,"Terrain excluded");Need(!c.TryContact(e),"Dash damage");c.EndDash();Need(!c.TryContact(e),"Exit grace missing");for(int i=0;i<12;i++)Call(c,"FixedUpdate");Need(body.excludeLayers.value==(1<<12),"Masks not restored");Need(c.TryContact(e),"Permanent immunity");});
 Check("disabling contact restores collision exclusions",()=>{var p=Player();var c=p.gameObject.AddComponent<PlayerEnemyContact>();Call(c,"Awake");c.BeginDash();Call(c,"OnDisable");Need(p.GetComponent<Collider2D>().excludeLayers==0,"Leaked ignore mask");});
 Check("dead slime does not damage player",()=>{var p=Player();var c=p.gameObject.AddComponent<PlayerEnemyContact>();Call(c,"Awake");var e=Enemy();e.TakeDamage(3,Vector2.zero);Need(!c.TryContact(e)&&p.currentHealth==100,"Corpse deals damage");});
 Check("dash immunity does not suppress trap damage",()=>{var p=Player();var c=p.gameObject.AddComponent<PlayerEnemyContact>();Call(c,"Awake");c.BeginDash();Need(p.TryTakeDamage(20),"General invincibility accidentally enabled");});
 Check("health clamps at zero and rejects damage after death",()=>{var p=Player();p.TakeDamage(200);Need(p.currentHealth==0&&p.IsDead&&!p.TryTakeDamage(20),"Death state invalid");});
 Check("all six chunks appear before reuse and no immediate repeats",()=>{var g=new GameObject("Generator").AddComponent<LevelGenerator>();g.midChunks=Enumerable.Range(0,6).Select(i=>new WeightedChunk{chunkPrefab=new GameObject("Chunk "+i),length=10,weight=i==1?100:1}).ToArray();GameObject previous=null;for(int cycle=0;cycle<100;cycle++){var seen=new HashSet<GameObject>();for(int i=0;i<6;i++){var chosen=g.ChooseNextChunk(100);Need(chosen!=null&&chosen!=previous&&seen.Add(chosen),"Repeat or starvation");previous=chosen;}}});
 Check("chunk selection respects remaining space and ends when none fits",()=>{var g=new GameObject("Generator").AddComponent<LevelGenerator>();var shortChunk=new GameObject("Short");g.midChunks=new[]{new WeightedChunk{chunkPrefab=shortChunk,length=5},new WeightedChunk{chunkPrefab=new GameObject("Long"),length=20}};Need(g.ChooseNextChunk(10)==shortChunk,"Oversized chunk chosen");Need(g.ChooseNextChunk(10)==shortChunk,"Only fitting chunk cannot repeat");Need(g.ChooseNextChunk(4)==null,"Should terminate");});
 Check("24 sound assets decode and all gameplay cues exist",()=>{var clips=Resources.LoadAll<AudioClip>("SFX");Need(clips.Length==24,"Wrong clip count");foreach(var clip in clips)Need(clip.samples>0&&clip.length>0&&clip.length<5,"Invalid clip "+clip.name);foreach(var cue in new[]{"swing","dash","jump","air_jump","hurt","player_death","slime_hit","slime_death","land","step_snow","step_concrete","step_wood"})Need(clips.Any(c=>c.name.StartsWith(cue+"_")),"Missing "+cue);});
 Check("both scenes wired with balanced weights, contact and audio",()=>{foreach(var path in new[]{"Assets/Scenes/SampleScene.unity","Assets/Scenes/PaintedDimension.unity"}){EditorSceneManager.OpenScene(path);var p=UnityEngine.Object.FindAnyObjectByType<PlayerAttack>();Need(p.GetComponent<PlayerEnemyContact>()!=null&&p.GetComponent<PlayerMovementAudio>()!=null,"Missing components");Need(p.GetComponent<PlayerHealth>().iFramesDuration==2,"Wrong cooldown");var g=UnityEngine.Object.FindAnyObjectByType<LevelGenerator>();Need(g.midChunks.Length==6&&g.midChunks.All(c=>c.weight==10),"Wrong weights");}});
 File.WriteAllLines("audio-contact-results.txt",report);EditorApplication.Exit(failures==0?0:1);
 }
}
